## CHAPTER expression-evaluator

The expression evaluator executes parsed task expressions against a controlled scope. It should not have access to arbitrary Python builtins. Instead, every callable is an explicit function provided by the host: pure helpers for parameters, artifact lookups, path helpers, and registered tool wrappers. This constraint makes replay safe. A recovery process can evaluate expressions again to reconstruct derived values without accidentally invoking side effects, as long as side-effecting functions are excluded from replay scopes.

Scoping must be explicit. The evaluator receives a mapping from identifiers to values or functions. If an identifier is absent, evaluation fails immediately. If an identifier is present but not callable, a call site fails. Binary and unary operators should be total for the supported operand types. If the language allows mixed numeric types, conversion must be defined and tested. Lists and dictionaries should be immutable in the AST but may evaluate to mutable Python values; the host should treat evaluated values as read-only after validation.

The evaluator should distinguish recoverable evaluation errors from fatal host errors. Unknown names, type mismatches in arithmetic, and non-callable targets are task specification errors. An injected tool may raise a retryable error, but that error should be classified by the scheduler, not swallowed by the evaluator. The evaluator should preserve exception chaining where useful, but it should not catch tool exceptions to invent a status. That policy belongs to the retry and scheduler layers.

Invariants include determinism for pure scopes, no dynamic code execution, and no reliance on Python globals beyond the injected functions. The evaluator must also be free of mutable global state. If a helper needs configuration, it receives it through closure or scope. The worked example manually builds an AST equivalent to a call to `tool` with an argument computed from `param`. It evaluates without invoking a subprocess, because the `tool` helper simply returns a structured representation. This keeps the example pure and suitable for unit testing.

```python
from dataclasses import dataclass
from typing import Any, Callable, Dict, Mapping, Tuple

@dataclass(frozen=True)
class Number:
    value: float

@dataclass(frozen=True)
class String:
    value: str

@dataclass(frozen=True)
class Identifier:
    name: str

@dataclass(frozen=True)
class Boolean:
    value: bool

@dataclass(frozen=True)
class ListLiteral:
    items: tuple

@dataclass(frozen=True)
class DictLiteral:
    pairs: tuple

@dataclass(frozen=True)
class Call:
    target: Any
    args: tuple

@dataclass(frozen=True)
class BinaryOp:
    op: str
    left: Any
    right: Any

@dataclass(frozen=True)
class UnaryOp:
    op: str
    operand: Any

class EvalError(Exception):
    pass

class Evaluator:
    def __init__(self, functions: Mapping[str, Callable[..., Any]]) -> None:
        self.functions = functions

    def evaluate(self, node: Any, scope: Mapping[str, Any]) -> Any:
        if isinstance(node, Number):
            return node.value
        if isinstance(node, String):
            return node.value
        if isinstance(node, Boolean):
            return node.value
        if isinstance(node, ListLiteral):
            return [self.evaluate(item, scope) for item in node.items]
        if isinstance(node, DictLiteral):
            result = {}
            for key, value in node.pairs:
                evaluated_key = self.evaluate(key, scope)
                if not isinstance(evaluated_key, (str, int, float, bool)):
                    raise EvalError("dictionary key must be hashable primitive")
                result[evaluated_key] = self.evaluate(value, scope)
            return result
        if isinstance(node, Identifier):
            if node.name in scope:
                return scope[node.name]
            if node.name in self.functions:
                return self.functions[node.name]
            raise EvalError("unknown name " + node.name)
        if isinstance(node, Call):
            target = self.evaluate(node.target, scope)
            if not callable(target):
                raise EvalError("call target is not callable")
            args = tuple(self.evaluate(argument, scope) for argument in node.args)
            return target(*args)
        if isinstance(node, UnaryOp):
            value = self.evaluate(node.operand, scope)
            if node.op == "-":
                return -value
            if node.op == "!":
                return not bool(value)
            raise EvalError("unsupported unary operator")
        if isinstance(node, BinaryOp):
            left = self.evaluate(node.left, scope)
            right = self.evaluate(node.right, scope)
            if node.op == "+":
                return left + right
            if node.op == "-":
                return left - right
            if node.op == "*":
                return left * right
            if node.op == "/":
                return left / right
            if node.op == "==":
                return left == right
            if node.op == "!=":
                return left != right
            if node.op == "<":
                return left < right
            if node.op == "<=":
                return left <= right
            if node.op == ">":
                return left > right
            if node.op == ">=":
                return left >= right
            raise EvalError("unsupported binary operator")
        raise EvalError("unknown node type")

def param(key: str, default: Any = None) -> Any:
    values = {"repo_root": "/workspace/repo"}
    return values.get(key, default)

def tool(name: str, args: Dict[str, Any]) -> Dict[str, Any]:
    return {"tool": name, "args": args}

args_ast = DictLiteral((
    (String("root"), Call(Identifier("param"), (String("repo_root"),))),
))
ast = Call(Identifier("tool"), (String("lint"), args_ast))
evaluator = Evaluator({"param": param})
print(evaluator.evaluate(ast, {"tool": tool}))
```

## CHAPTER type-validation

Type validation protects the boundary between task definitions and tools. An expression can evaluate to almost any Python object, but a tool request must have stable fields and compatible types. The validator defines schemas for common shapes such as a tool call, a task, or an artifact reference. It then walks the evaluated value and checks every field against the schema. This avoids a class of runtime failures where a tool receives a string where it expects an integer or a missing required argument.

Validation should be structural but opinionated. Strings are strings, integers are integers, booleans are not integers, lists are lists, and mappings are mappings. Coercion is dangerous because it hides mistakes. If a task file contains `"30000"` for a millisecond limit, the validator should reject it unless the schema explicitly allows a text numeric form. For dependencies, the validator should ensure the value is a list of strings. For call arguments, the validator should ensure the value is a mapping. For nested schemas, recursion must include the path so errors are diagnosable.

The validator must support optional fields but not optional required fields by accident. A missing required field is an error, even if the tool could default it. Defaults belong in the task spec language or tool schema, not in the validator, because recovery needs the effective value stored. The validator also needs a closed set of type names. Unknown type names should fail validation, because that usually means a schema was copied incorrectly or an experimental field escaped into production.

Error handling uses a dedicated exception carrying a path. A message like `root.call.args.root must be string` is more useful than a traceback. The validator does not modify values, truncate strings, or normalize paths. Those transformations are separate operations that may have their own security and type rules. The worked example defines schemas for a task and a tool call, validates a dictionary that looks like the JSON form of a task, and prints the schema name on success.

```python
from dataclasses import dataclass
from typing import Any, Dict, Mapping, Optional, Tuple

class TypeCheckError(Exception):
    def __init__(self, path: str, message: str) -> None:
        super().__init__(f"{path}: {message}")
        self.path = path
        self.message = message

@dataclass(frozen=True)
class FieldSpec:
    name: str
    type_name: str
    optional: bool = False

@dataclass(frozen=True)
class Schema:
    name: str
    fields: Tuple[FieldSpec, ...]

class TypeValidator:
    def __init__(self, schemas: Mapping[str, Schema]) -> None:
        self.schemas = schemas

    def check_value(self, value: Any, type_name: str, path: str) -> None:
        if type_name == "string":
            if not isinstance(value, str):
                raise TypeCheckError(path, "must be string")
        elif type_name == "integer":
            if isinstance(value, bool) or not isinstance(value, int):
                raise TypeCheckError(path, "must be integer")
        elif type_name == "boolean":
            if not isinstance(value, bool):
                raise TypeCheckError(path, "must be boolean")
        elif type_name == "mapping":
            if not isinstance(value, Mapping):
                raise TypeCheckError(path, "must be mapping")
        elif type_name == "string_list":
            if not isinstance(value, list) or any(not isinstance(item, str) for item in value):
                raise TypeCheckError(path, "must be list of strings")
        elif type_name == "tool_call":
            if not isinstance(value, Mapping):
                raise TypeCheckError(path, "tool call must be mapping")
            if "name" not in value or not isinstance(value["name"], str):
                raise TypeCheckError(path + ".name", "tool name must be string")
            if "args" not in value or not isinstance(value["args"], Mapping):
                raise TypeCheckError(path + ".args", "tool args must be mapping")
        elif type_name in self.schemas:
            self.validate_schema(self.schemas[type_name], value, path)
        else:
            raise TypeCheckError(path, "unknown type name " + type_name)

    def validate_schema(self, schema: Schema, value: Any, path: str = "root") -> None:
        if not isinstance(value, Mapping):
            raise TypeCheckError(path, "schema value must be mapping")
        for field in schema.fields:
            child_path = path + "." + field.name
            if field.name not in value:
                if field.optional:
                    continue
                raise TypeCheckError(child_path, "required field is missing")
            self.check_value(value[field.name], field.type_name, child_path)

tool_call_schema = Schema("tool_call", (
    FieldSpec("name", "string"),
    FieldSpec("args", "mapping"),
))
task_schema = Schema("task", (
    FieldSpec("name", "string"),
    FieldSpec("version", "string"),
    FieldSpec("deps", "string_list"),
    FieldSpec("call", "tool_call"),
))
schemas = {"task": task_schema, "tool_call": tool_call_schema}
validator = TypeValidator(schemas)
task_value = {
    "name": "lint",
    "version": "1",
    "deps": ["prepare"],
    "call": {"name": "python.lint", "args": {"root": "/workspace/repo"}},
}
validator.validate_schema(task_schema, task_value)
print("validated", task_schema.name)
```

## CHAPTER dependency-graph

The dependency graph turns task names and dependencies into execution edges. It should validate the graph before scheduling begins. Each node is a task. Each edge from a dependency to a dependent means the dependency must complete before the dependent may be considered ready. Duplicate names are rejected. Unknown dependencies are rejected. The graph may store successors and indegrees for efficient traversal, but the source of truth remains the task definitions.

A graph invariant is that all edges point from completed work to newly available work. That means the scheduler can answer readiness questions by checking whether every dependency of a task appears in the completed set. If dependencies are missing, an unknown dependency could make a task wait forever or execute without required inputs. If duplicate tasks are allowed, the scheduler could submit two attempts for the same logical task and write conflicting artifacts. Therefore the graph constructor should fail fast.

Topological order is useful for validation and for simple sequential runs. A production parallel scheduler still uses dependency readiness rather than a single fixed order, because independent tasks can overlap. The topological sort should be deterministic, often by sorting ready nodes by name. That determinism helps tests and replay. The scheduler may consume the graph incrementally, but it should never mutate the graph’s edge sets while scheduling. Mutable execution state belongs in the scheduler.

Error handling separates structural errors from execution errors. Missing dependency and duplicate task are structural and occur before journal writes. A cycle is detected either during construction or by a dedicated cycle detector. If the graph contains a cycle, no task in the cycle can become ready, so the scheduler would otherwise hang. The graph may call a cycle checker or provide its own topological validation. The worked example builds a graph with prepare, lint, test, and package, prints a deterministic topological order, and demonstrates readiness after a subset of tasks completes.

```python
import heapq
from collections import defaultdict
from dataclasses import dataclass
from typing import Dict, List, Tuple

@dataclass(frozen=True)
class Task:
    name: str
    deps: Tuple[str, ...]

class DependencyGraph:
    def __init__(self, tasks: List[Task]) -> None:
        self.tasks: Dict[str, Task] = {}
        self.successors: Dict[str, List[str]] = defaultdict(list)
        self.indegree: Dict[str, int] = {}
        for task in tasks:
            if task.name in self.tasks:
                raise ValueError("duplicate task " + task.name)
            self.tasks[task.name] = task
            self.successors.setdefault(task.name, [])
            self.indegree.setdefault(task.name, 0)
        for task in tasks:
            for dep in task.deps:
                if dep not in self.tasks:
                    raise ValueError("missing dependency " + dep + " for task " + task.name)
                self.successors[dep].append(task.name)
                self.indegree[task.name] += 1

    def topo_order(self) -> List[str]:
        indegree = dict(self.indegree)
        heap = [name for name, value in indegree.items() if value == 0]
        heapq.heapify(heap)
        order: List[str] = []
        while heap:
            node = heapq.heappop(heap)
            order.append(node)
            for successor in self.successors.get(node, []):
                indegree[successor] -= 1
                if indegree[successor] == 0:
                    heapq.heappush(heap, successor)
        if len(order) != len(self.tasks):
            raise ValueError("graph contains a cycle")
        return order

    def ready_after(self, done: set) -> List[str]:
        done_set = set(done)
        ready = []
        for name, task in self.tasks.items():
            if name in done_set:
                continue
            if all(dep in done_set for dep in task.deps):
                ready.append(name)
        return sorted(ready)

tasks = [
    Task("prepare", ()),
    Task("lint", ("prepare",)),
    Task("test", ("lint",)),
    Task("package", ("lint", "test")),
]
graph = DependencyGraph(tasks)
print(graph.topo_order())
print(graph.ready_after({"prepare", "lint"}))
```

## CHAPTER cycle-detection

Cycle detection protects scheduling before resources are consumed. A cycle in a dependency graph means no task in the cycle can ever become ready, because each task waits on another task in the same cycle. The scheduler could detect this indirectly by waiting forever, but that is expensive and obscure. An explicit detector reports the cycle as part of validation and prevents a run from starting with an impossible task set.

The standard method is depth-first search with colors. White means unvisited, gray means on the current recursion stack, black means completed. When search reaches a gray node, it has found a back edge. The cycle consists of the portion of the current stack from that node to the current node. Recording the stack allows the error message to name the actual tasks involved, which is essential when users edit task files manually. For large graphs, recursion depth may be an issue, so production implementations may use an iterative DFS with an explicit stack.

The detector should use the same edge direction as the scheduler. If edges go from task to dependencies, a cycle is still a cycle. If edges go from dependency to dependent, a cycle is also still a cycle. The important invariant is consistency: do not mix directions, because mixed direction can hide or invent cycles. The detector must also validate dependencies, because a reference to an unknown task is a structural error, not a cycle. A missing dependency cannot be ignored, because recovery later would not be able to compute readiness.

Error handling reports cycles as tuples or lists. If multiple cycles share nodes, the detector may report several distinct cycles or one representative set of edges. It is acceptable to return unique cycles by canonicalizing the tuple order. If there are no cycles, the detector returns an empty collection. The scheduler can then proceed safely. The worked example creates a graph with a cycle involving build, test, and lint, plus an independent node, and shows that the detector returns at least one cycle containing the offending tasks.

```python
from dataclasses import dataclass
from typing import Dict, List, Tuple

@dataclass(frozen=True)
class Task:
    name: str
    deps: Tuple[str, ...]

def detect_cycles(tasks: List[Task]) -> List[Tuple[str, ...]]:
    adjacency: Dict[str, Tuple[str, ...]] = {}
    for task in tasks:
        if task.name in adjacency:
            raise ValueError("duplicate task " + task.name)
        adjacency[task.name] = task.deps
    colors: Dict[str, int] = {}
    path: List[str] = []
    cycles: List[Tuple[str, ...]] = []

    def dfs(node: str) -> None:
        colors[node] = 1
        path.append(node)
        for neighbor in adjacency.get(node, ()):
            if neighbor not in adjacency:
                raise ValueError("missing dependency " + neighbor + " for task " + node)
            color = colors.get(neighbor, 0)
            if color == 0:
                dfs(neighbor)
            elif color == 1:
                start = path.index(neighbor)
                cycle = tuple(path[start:])
                if cycle not in cycles:
                    cycles.append(cycle)
        path.pop()
        colors[node] = 2

    for node in sorted(adjacency):
        if colors.get(node, 0) == 0:
            dfs(node)
    return cycles

tasks = [
    Task("prepare", ()),
    Task("build", ("test",)),
    Task("test", ("lint",)),
    Task("lint", ("build",)),
]
cycles = detect_cycles(tasks)
print(cycles)
```

## CHAPTER scheduler

The scheduler turns graph readiness into submitted work. It owns mutable execution state: completed tasks, failed tasks, pending submissions, and results. The scheduler should never submit a task whose dependencies have not completed successfully. It should also never submit a task that has already completed, failed, or is already pending. These invariants prevent duplicate side effects and preserve deterministic artifact ownership.

A common design uses a thread pool and a future mapping. The scheduler repeatedly schedules all ready tasks up to worker capacity, waits for one future to complete, records the outcome, and repeats. When a task fails, dependents should be marked failed or blocked without execution. If cancellation is requested, the scheduler stops submitting new tasks and attempts to cancel futures that have not started. Already running tasks must cooperate through cancellation tokens and resource deadlines. The scheduler should not assume that cancelling a future kills a subprocess; that is the tool protocol and resource layer responsibility.

The scheduler must be tolerant of mixed outcomes. A task that finishes after cancellation may be recorded as completed if the cancellation arrived too late, but the run outcome should reflect that the run was cancelled. This avoids pretending that a completed side effect did not happen. Results should be immutable dictionaries containing task name, status, payload, and error. The scheduler may propagate exceptions from work functions into failed status entries, but it should not crash the whole pool for a single task failure unless the failure is catastrophic.

Worked example uses four tasks in a diamond dependency pattern: prepare, lint, test, and package. A simple work function sleeps briefly and returns its name. The scheduler executes with two workers and returns statuses for all tasks. The example is small enough to inspect, and it preserves the invariants needed by later persistence and retry chapters.

```python
import time
from concurrent.futures import FIRST_COMPLETED, ThreadPoolExecutor, wait
from dataclasses import dataclass
from threading import Event
from typing import Callable, Dict, Tuple

@dataclass(frozen=True)
class Job:
    name: str
    deps: Tuple[str, ...]

class Scheduler:
    def __init__(self, jobs: Tuple[Job, ...], work: Callable[[str], object], max_workers: int, cancel: Event = None) -> None:
        self.jobs = {job.name: job for job in jobs}
        self.work = work
        self.max_workers = max_workers
        self.cancel = cancel or Event()
        self.completed = set()
        self.failed = set()
        self.pending = set()
        self.results: Dict[str, Dict[str, object]] = {}

    def _ready(self):
        for job in self.jobs.values():
            if job.name in self.completed or job.name in self.failed or job.name in self.pending:
                continue
            if any(dep in self.failed for dep in job.deps):
                self.failed.add(job.name)
                self.results[job.name] = {"status": "failed", "error": "blocked by dependency failure"}
                continue
            if all(dep in self.completed for dep in job.deps):
                return job
        return None

    def _execute(self, job: Job) -> object:
        try:
            payload = self.work(job.name)
            self.completed.add(job.name)
            self.results[job.name] = {"status": "completed", "payload": payload}
            return payload
        except Exception as exc:
            self.failed.add(job.name)
            self.results[job.name] = {"status": "failed", "error": str(exc)}
            raise
        finally:
            self.pending.discard(job.name)

    def run(self) -> Dict[str, Dict[str, object]]:
        if not self.jobs:
            return self.results
        with ThreadPoolExecutor(max_workers=self.max_workers) as pool:
            futures: Dict[object, str] = {}
            while True:
                while True:
                    if self.cancel.is_set():
                        break
                    job = self._ready()
                    if job is None:
                        break
                    self.pending.add(job.name)
                    future = pool.submit(self._execute, job)
                    futures[future] = job.name
                if self.cancel.is_set():
                    for future in futures:
                        future.cancel()
                    break
                if not futures:
                    break
                done, _ = wait(futures, timeout=0.05, return_when=FIRST_COMPLETED)
                for future in done:
                    futures.pop(future, None)
                    try:
                        future.result()
                    except Exception:
                        pass
                if len(self.completed) + len(self.failed) == len(self.jobs):
                    break
        return self.results

def work(name: str) -> str:
    time.sleep(0.01)
    return name

jobs = (
    Job("prepare", ()),
    Job("lint", ("prepare",)),
    Job("test", ("prepare",)),
    Job("package", ("lint", "test")),
)
scheduler = Scheduler(jobs, work, max_workers=2)
print(scheduler.run())
```

## CHAPTER retry-policy

Retry is a policy, not a general error handler. A tool may fail for reasons that are safe to repeat, such as transient network flakiness, temporary filesystem contention, or a runner process that timed out. A tool may also fail for reasons that should never be retried, such as invalid input, path outside workspace, or a missing executable. The retry policy must distinguish these cases and enforce a bounded number of attempts.

Backoff should reduce pressure while keeping recovery deterministic enough for testing. Exponential backoff is common, and full jitter can reduce thundering herds when many tasks retry at once. If deterministic replay matters, jitter should be derived from a stable seed such as task id and attempt number. That makes logs reproducible and load tests less noisy. Sleep should be interruptible by cancellation so that a run can stop while waiting between attempts.

The retry executor should return the result on first success. On non-retryable error, it should rethrow without sleep. On exhausted retryable error, it should raise a retry error carrying the final exception and attempt count. The scheduler can then classify the task as failed and record the last error. The executor must not retry cancellation unless the policy explicitly declares cancellation retryable, which is rare and dangerous because the user may be trying to stop resource consumption.

Invariants include a positive maximum attempt count, nonnegative backoff, and a closed list of retryable markers. The retry layer should not mutate task input or create new request ids for the same logical attempt unless tool idempotency requires it. The worked example implements a small retry executor with deterministic jitter based on hashing. A flaky function fails with a transient error twice, then succeeds. This demonstrates that retry is bounded, observable, and integrated with cancellation checks.

```python
import hashlib
import threading
import time
from dataclasses import dataclass
from typing import Tuple

@dataclass(frozen=True)
class RetryPolicy:
    max_attempts: int
    base_backoff_ms: int
    retryable_errors: Tuple[str, ...]

class RetryError(Exception):
    def __init__(self, message: str, attempts: int) -> None:
        super().__init__(message)
        self.attempts = attempts

def deterministic_sleep_seconds(policy: RetryPolicy, task_id: str, attempt: int) -> float:
    seed = hashlib.sha256((task_id + "|" + str(attempt)).encode("utf-8")).hexdigest()
    jitter = (int(seed, 16) % 101) / 100.0
    return policy.base_backoff_ms * (2 ** (attempt - 1)) / 1000.0 * (1.0 + jitter)

def execute_with_retry(fn, policy: RetryPolicy, task_id: str, cancel: threading.Event = None) -> object:
    last_error = None
    for attempt in range(1, policy.max_attempts + 1):
        if cancel and cancel.is_set():
            raise RetryError("cancelled before attempt", attempt)
        try:
            return fn()
        except RuntimeError as exc:
            message = str(exc)
            if not any(marker in message for marker in policy.retryable_errors):
                raise
            last_error = exc
            if attempt == policy.max_attempts:
                break
            sleep_seconds = deterministic_sleep_seconds(policy, task_id, attempt)
            if cancel:
                if cancel.wait(sleep_seconds):
                    raise RetryError("cancelled during backoff", attempt)
            else:
                time.sleep(sleep_seconds)
    raise RetryError(str(last_error), policy.max_attempts)

policy = RetryPolicy(max_attempts=3, base_backoff_ms=1, retryable_errors=("transient",))
attempts_box = {"count": 0}

def flaky() -> str:
    attempts_box["count"] += 1
    if attempts_box["count"] < 3:
        raise RuntimeError("transient tool failure")
    return "lint passed"

cancel = threading.Event()
result = execute_with_retry(flaky, policy, "retry-demo", cancel)
print(result, attempts_box["count"])
```

## CHAPTER cancellation

Cancellation must be cooperative and hierarchical. The runner starts with a root token for the whole run. Each task gets a child token. Cancelling a parent cancels descendants. Cancelling a child does not cancel its parent. This structure lets a run cancel one tool without cancelling every other independent task, while still allowing a global stop to reach all active work quickly.

The scheduler cannot cancel side effects instantly. A future that has not started may be cancelled before it runs. A future that has started may need to poll a token, respond to a deadline, or wait for its subprocess to exit. Tools should therefore receive the token and check it at safe points. The token should offer a sleep method that returns immediately when cancellation is set. That keeps backoff and polling loops responsive without busy waiting.

Cancellation has a distinct status from failure. A cancelled task may leave a partial artifact, but the runner must not treat it as completed. The journal records task_started and task_cancelled events, and recovery may mark the task as needing rerun unless tool idempotency proves otherwise. If cancellation arrives after completion, the task can remain completed, but the run as a whole may still be marked cancelled. This preserves truth about side effects that already happened.

Error handling should not convert every timeout into cancellation by default. A wall limit can cause a task to fail with timeout while the run continues. A global cancel should propagate to all active tasks. The worked example creates a parent and child token, runs a task that sleeps in steps, cancels the parent through a timer, and observes that the child stops early. This demonstrates the core hierarchy and cooperative polling.

```python
import threading
import time
from typing import List

class CancellationToken:
    def __init__(self, parent: "CancellationToken" = None) -> None:
        self.parent = parent
        self._event = threading.Event()
        self._children: List[CancellationToken] = []
        if parent is not None:
            parent._children.append(self)

    def cancel(self) -> None:
        self._event.set()
        for child in self._children:
            child.cancel()

    def is_cancelled(self) -> bool:
        return self._event.is_set()

    def sleep(self, seconds: float) -> bool:
        return self._event.wait(timeout=seconds)

def run_tool(token: CancellationToken, name: str) -> dict:
    for step in range(5):
        if token.sleep(0.01):
            return {"status": "cancelled", "task": name, "step": step}
    return {"status": "completed", "task": name}

def demo() -> dict:
    parent = CancellationToken()
    child = CancellationToken(parent)
    result = {}

    def worker() -> None:
        result["task_result"] = run_tool(child, "compile")

    thread = threading.Thread(target=worker)
    thread.start()
    timer = threading.Timer(0.035, parent.cancel)
    timer.start()
    thread.join()
    timer.cancel()
    return result

print(demo())
```

## CHAPTER event-journal

The event journal records lifecycle facts in append-only order. Every important transition writes one event: run started, task scheduled, task started, task finished, task failed, task cancelled, checkpoint written, and run finished. Events are JSON lines so they can be read without a database and appended atomically as single lines. A stable sequence number gives causal order inside one journal, while a previous hash creates a tamper-evident chain.

The journal should not contain large payloads. Task output can be huge; the journal should store artifact references, sizes, status, and small summaries. Large payloads make fsync costly and replay slower. The data field should be bounded and normalized. The journal writer should flush and fsync according to durability policy. A local runner may fsync every event for crash safety, or batch under explicit configuration. Whatever policy is chosen, the invariant is that a checkpoint can identify the sequence through which it is consistent.

Validation is cheap and necessary. A reader recomputes the hash of each event’s payload and compares it to the stored event hash. It also checks that sequence numbers increase by one and that each previous hash matches the previous event hash. If any check fails, the journal is corrupt and recovery must refuse to invent a safe state. The corrupt journal should be preserved for forensics, then a repair path can truncate only if operations explicitly decides.

Error handling distinguishes write failure from append corruption. A write failure should stop the run because no durable record exists. A read failure should stop recovery because the state is unknown. The worked example appends start and finish events to a temporary file, iterates over them, validates the chain, and prints the count. This shows the minimal durable log needed by checkpoint recovery.

```python
import hashlib
import json
import tempfile
from dataclasses import dataclass
from typing import Any, Dict, Iterator

@dataclass(frozen=True)
class Event:
    seq: int
    run_id: str
    name: str
    data: Dict[str, Any]
    previous_hash: str
    event_hash: str

def hash_event_payload(payload: Dict[str, Any]) -> str:
    without_hash = {
        "seq": payload["seq"],
        "run_id": payload["run_id"],
        "name": payload["name"],
        "data": payload["data"],
        "previous_hash": payload["previous_hash"],
    }
    serialized = json.dumps(without_hash, sort_keys=True, separators=(",", ":"))
    return hashlib.sha256(serialized.encode("utf-8")).hexdigest()

class Journal:
    def __init__(self, path: str) -> None:
        self.path = path
        self.next_seq = 1
        self.previous_hash = "root"

    def append(self, run_id: str, name: str, data: Dict[str, Any]) -> Event:
        payload = {
            "seq": self.next_seq,
            "run_id": run_id,
            "name": name,
            "data": data,
            "previous_hash": self.previous_hash,
        }
        digest = hash_event_payload(payload)
        payload["event_hash"] = digest
        with open(self.path, "a", encoding="utf-8") as handle:
            handle.write(json.dumps(payload, sort_keys=True) + "\n")
            handle.flush()
        self.next_seq += 1
        self.previous_hash = digest
        return Event(**payload)

    def iter_events(self) -> Iterator[Event]:
        with open(self.path, "r", encoding="utf-8") as handle:
            for line in handle:
                if not line.strip():
                    continue
                yield Event(**json.loads(line))

    def validate(self) -> bool:
        previous = "root"
        expected_seq = 1
        for event in self.iter_events():
            if event.seq != expected_seq or event.previous_hash != previous:
                return False
            payload = {
                "seq": event.seq,
                "run_id": event.run_id,
                "name": event.name,
                "data": event.data,
                "previous_hash": event.previous_hash,
            }
            if hash_event_payload(payload) != event.event_hash:
                return False
            previous = event.event_hash
            expected_seq += 1
        return True

with tempfile.TemporaryDirectory() as tmp:
    journal = Journal(tmp + "/events.jsonl")
    journal.append("run-1", "task_started", {"task": "lint"})
    journal.append("run-1", "task_finished", {"task": "lint", "status": "completed"})
    events = list(journal.iter_events())
    print(len(events), journal.validate())
```

## CHAPTER atomic-storage

Atomic storage guarantees that readers never observe a partial file. The standard recipe is to write to a temporary file in the same directory, flush the file buffers, fsync the file, rename it over the target, and fsync the containing directory. Rename is atomic on POSIX filesystems when source and target share the same filesystem. Putting the temporary file next to the target avoids cross-device copy and keeps cleanup simple.

Artifacts, checkpoint snapshots, and lock manifests should use atomic writes when consistency matters. The journal is append-only and does not usually replace existing content, so it relies on line-based fsync and hash chain validation. Checkpoints are replaced, not appended, because a snapshot is the current consistent state summary. Atomic replacement means a crash either leaves the previous checkpoint or the new checkpoint, never a truncated mixture.

Error handling must clean up temporary files. If writing, flushing, fsyncing, or renaming fails, the temp file should be removed if it still exists. The original target must remain unchanged when the temp operation fails. If fsyncing the directory is unsupported on a platform, the implementation should make that limitation explicit in operations documentation. The worked example writes a report, then replaces it with a second version. It shows that the visible target is always complete and that failed attempts do not expose half-written bytes.

Invariants include uniqueness of temporary names, same-directory placement, and no rename across filesystems unless a fallback is explicitly designed. The storage helper should refuse paths outside the workspace because atomic rename cannot protect global filesystem assumptions. It should also not overwrite unrelated directories. A robust helper validates the target parent, creates missing directories only under the workspace, and returns the final path on success.

```python
import os
import tempfile
from pathlib import Path

def fsync_directory(path: Path) -> None:
    handle = os.open(str(path), os.O_RDONLY)
    try:
        os.fsync(handle)
    finally:
        os.close(handle)

def atomic_write_bytes(target: Path, data: bytes) -> Path:
    if not target.parent.exists():
        target.parent.mkdir(parents=True, exist_ok=True)
    temp_fd, temp_name = tempfile.mkstemp(prefix=target.name + ".", dir=str(target.parent))
    try:
        with os.fdopen(temp_fd, "wb") as handle:
            handle.write(data)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(temp_name, str(target))
        fsync_directory(target.parent)
        return target
    except BaseException:
        try:
            os.unlink(temp_name)
        except FileNotFoundError:
            pass
        raise

with tempfile.TemporaryDirectory() as tmp:
    artifact = Path(tmp) / "reports" / "lint.txt"
    atomic_write_bytes(artifact, b"first report")
    atomic_write_bytes(artifact, b"second report")
    print(artifact.exists(), artifact.read_bytes())
    print(artifact.parent.name)
```

## CHAPTER checkpoint-recovery

Checkpoint recovery reconstructs a safe task state after an interruption. The checkpoint stores completed and failed task names, the last journal sequence incorporated, and optionally resource usage summaries. The journal tail is replayed to absorb events that happened after the checkpoint. Recovery must not regress completed tasks: once a task completed and its artifacts are durable, replayed events cannot mark it incomplete. If an event contradicts a checkpoint, the safest response is to stop recovery or quarantine the run.

A checkpoint is not a full result. It is a compact summary plus a pointer into the event stream. That keeps fsync cost low. During normal operation, the runner may write a checkpoint after a batch of completed tasks or periodically by elapsed time. During recovery, the runner reads the checkpoint, skips events up to its sequence, and applies later events. Task_started events after the checkpoint without matching task_finished events produce running tasks. Running tasks are not assumed completed; they are re-executed or marked failed depending on tool idempotency and policy.

Invariants include monotonic sequence, immutable completed set, and deterministic application order. Recovery must process events in sequence order, not file system mtime order. It must ignore duplicate events if the journal writer accidentally retried a line, because replay should be idempotent. It must treat unknown event names conservatively, either ignoring them with a warning if they are safe metadata or failing if they could affect scheduling.

Error handling should preserve evidence. If the checkpoint is missing, recovery can replay from the beginning. If the checkpoint is corrupt, recovery should not create a partial state. If the journal tail is corrupt, the last verified event becomes the limit. The worked example creates a checkpoint that says prepare is complete, replays a journal tail where lint finished and test started, and returns completed plus running sets. This matches the core recovery contract for the scheduler.

```python
import json
import os
import tempfile
from typing import Any, Dict, List, Tuple

def atomic_write_json(path: str, value: Dict[str, Any]) -> None:
    temp = path + ".tmp"
    with open(temp, "w", encoding="utf-8") as handle:
        json.dump(value, handle, sort_keys=True)
        handle.flush()
        os.fsync(handle.fileno())
    os.replace(temp, path)

def load_json(path: str) -> Dict[str, Any]:
    with open(path, "r", encoding="utf-8") as handle:
        return json.load(handle)

def recover(checkpoint: Dict[str, Any], events: List[Dict[str, Any]]) -> Tuple[List[str], List[str]]:
    completed = set(checkpoint.get("completed", []))
    failed = set(checkpoint.get("failed", []))
    started: Dict[str, int] = {}
    finished: Dict[str, int] = {}
    last_seq = int(checkpoint.get("last_seq", 0))
    for event in events:
        if event["seq"] <= last_seq:
            continue
        name = event["name"]
        task = event.get("data", {}).get("task")
        if not task:
            continue
        if name == "task_started":
            started[task] = event["seq"]
        elif name == "task_finished":
            if event["data"].get("status") == "completed":
                completed.add(task)
            else:
                failed.add(task)
            finished[task] = event["seq"]
    running = [task for task in started if task not in finished]
    return sorted(completed), sorted(running)

with tempfile.TemporaryDirectory() as tmp:
    checkpoint_path = os.path.join(tmp, "checkpoint.json")
    checkpoint = {"completed": ["prepare"], "failed": [], "last_seq": 1}
    atomic_write_json(checkpoint_path, checkpoint)
    events = [
        {"seq": 2, "name": "task_started", "data": {"task": "lint"}},
        {"seq": 3, "name": "task_finished", "data": {"task": "lint", "status": "completed"}},
        {"seq": 4, "name": "task_started", "data": {"task": "test"}},
    ]
    recovered_checkpoint = load_json(checkpoint_path)
    completed, running = recover(recovered_checkpoint, events)
    print(completed, running)
```

## CHAPTER resource-limits

Resource limits bound the blast radius of a task. Wall time limits must kill the process and clean its file descriptors. Output limits prevent runaway logs and memory exhaustion from capturing stdout or stderr. CPU limits are harder with pure standard library code and often rely on operating system mechanisms such as job objects, cgroups, ulimit, or process priorities. A portable runner can enforce wall time and output size directly and delegate cpu accounting to platform tools when available.

A wall deadline starts when the task is submitted, not when the scheduler wakes up. The deadline should use a monotonic clock so system time adjustments cannot extend or truncate execution. The process is spawned with its output pipes in non-blocking reader threads or with a timeout on communicate. For untrusted tools, reader threads and output accumulation with early kill are safer than waiting for a full stream that may never finish. When output exceeds the limit, the runner should kill the process and report output_limit rather than truncating silently.

Output handling should retain a bounded prefix for diagnostics. The runner may also store the last chunk, because many failures appear at the end. However, storing both without control multiplies memory. A simple rule is to keep the first configured bytes for startup context and the last configured bytes for failure context, rotating only when the total is exceeded. This chapter example uses a single bounded prefix for clarity and production notes for rotation.

Error handling must distinguish successful completion from a killed process. A nonzero return code is a task failure unless the tool protocol explicitly encodes an acceptable failure. A wall timeout produces a status of wall_timeout with a negative or killed return code. An output limit produces output_limit. Cancellation remains separate. The worked example runs a Python command that emits too much output, then another command that sleeps too long, and prints bounded statuses and byte counts.

```python
import subprocess
import sys
import threading
import time
from dataclasses import dataclass

@dataclass(frozen=True)
class ResourceLimits:
    wall_ms: int
    output_bytes: int

@dataclass(frozen=True)
class BoundedResult:
    status: str
    stdout: bytes
    stderr: bytes
    returncode: int

def drain_stream(pipe, chunks, limit_event, limit_bytes):
    while True:
        chunk = pipe.read(1024)
        if not chunk:
            break
        chunks.append(chunk)
        total = sum(len(item) for item in chunks)
        if total > limit_bytes:
            limit_event.set()
            return

def run_bounded(command, limits: ResourceLimits, cwd=None, env=None) -> BoundedResult:
    process = subprocess.Popen(command, stdout=subprocess.PIPE, stderr=subprocess.PIPE, cwd=cwd, env=env)
    stdout_chunks = []
    stderr_chunks = []
    limit_event = threading.Event()
    deadline = time.monotonic() + limits.wall_ms / 1000.0
    stdout_thread = threading.Thread(target=drain_stream, args=(process.stdout, stdout_chunks, limit_event, limits.output_bytes))
    stderr_thread = threading.Thread(target=drain_stream, args=(process.stderr, stderr_chunks, limit_event, limits.output_bytes))
    stdout_thread.start()
    stderr_thread.start()
    status = "completed"
    while True:
        if time.monotonic() > deadline:
            process.kill()
            status = "wall_timeout"
            break
        if limit_event.is_set():
            process.kill()
            status = "output_limit"
            break
        if process.poll() is not None and not stdout_thread.is_alive() and not stderr_thread.is_alive():
            break
        time.sleep(0.005)
    stdout_thread.join()
    stderr_thread.join()
    returncode = process.wait()
    stdout = b"".join(stdout_chunks)[: limits.output_bytes]
    stderr = b"".join(stderr_chunks)[: limits.output_bytes]
    return BoundedResult(status, stdout, stderr, returncode)

noisy_code = "import sys; sys.stdout.write('x' * 100)"
noisy = run_bounded([sys.executable, "-c", noisy_code], ResourceLimits(1000, 20))
print(noisy.status, len(noisy.stdout), noisy.returncode)

slow_code = "import time; time.sleep(2)"
slow = run_bounded([sys.executable, "-c", slow_code], ResourceLimits(100, 1000))
print(slow.status, slow.returncode)
```

## CHAPTER tool-protocol

The tool protocol defines how the runner calls external or internal capabilities. A request contains a request id, tool name, arguments, and limits. A result contains the same request id, status, payload, and optional error. This schema gives the journal, observability layer, and retry policy a stable shape. Internal tools can implement the same protocol without subprocess boundaries, while external tools can be isolated processes communicating by JSON.

Tool handlers should validate their request before performing side effects. They should not assume that the scheduler enforced every type rule, because tools may be invoked by tests, CLI utilities, or recovery diagnostics. Idempotency keys are useful when a tool creates files or submits external work. If the same request is retried after a timeout, the tool can detect an existing result and return the stored output rather than duplicating side effects. The runner should treat unknown status values as failures, because an unknown success status is ambiguous.

Registry errors are distinct from tool errors. Registering a duplicate tool name is a deployment error. Invoking an unknown tool is a contract error and should produce a structured failed result, not a raw traceback inside the scheduler. A handler exception should be converted into a failed result by the registry so the scheduler receives a uniform object. This also allows metrics and journal events to record tool failures without knowing each handler’s exception type.

The worked example registers a small subprocess tool. The tool reads a request from stdin, executes trusted Python code in the example, and writes a JSON response to stdout. The registry invokes it with limits and converts subprocess failures into structured results. This illustrates the serialization boundary and error taxonomy without requiring a separate executable script in the example.

```python
import json
import subprocess
import sys
from dataclasses import asdict, dataclass
from typing import Any, Callable, Dict, Optional

@dataclass(frozen=True)
class ToolRequest:
    request_id: str
    name: str
    args: Dict[str, Any]
    limits: Dict[str, int]

@dataclass(frozen=True)
class ToolResult:
    request_id: str
    status: str
    payload: Optional[Dict[str, Any]]
    error: Optional[str]

class ToolRegistry:
    def __init__(self) -> None:
        self.tools: Dict[str, Callable[[ToolRequest], ToolResult]] = {}

    def register(self, name: str, handler: Callable[[ToolRequest], ToolResult]) -> None:
        if name in self.tools:
            raise ValueError("duplicate tool " + name)
        self.tools[name] = handler

    def invoke(self, request: ToolRequest) -> ToolResult:
        handler = self.tools.get(request.name)
        if handler is None:
            return ToolResult(request.request_id, "failed", None, "unknown tool")
        try:
            return handler(request)
        except Exception as exc:
            return ToolResult(request.request_id, "failed", None, "tool raised " + str(exc))

def echo_handler(request: ToolRequest) -> ToolResult:
    source = (
        "import json, sys; "
        "req=json.load(sys.stdin); "
        "print(json.dumps({'status':'completed','text':req['args']['text']}))"
    )
    payload = json.dumps(asdict(request), sort_keys=True)
    timeout = request.limits.get("wall_ms", 1000) / 1000.0
    completed = subprocess.run(
        [sys.executable, "-c", source],
        input=payload,
        capture_output=True,
        text=True,
        timeout=timeout,
    )
    if completed.returncode != 0:
        return ToolResult(request.request_id, "failed", None, completed.stderr.strip() or "tool exited nonzero")
    try:
        result_payload = json.loads(completed.stdout)
    except json.JSONDecodeError as exc:
        return ToolResult(request.request_id, "failed", None, "invalid tool output: " + str(exc))
    status = str(result_payload.get("status", "completed"))
    return ToolResult(request.request_id, status, result_payload, None)

registry = ToolRegistry()
registry.register("echo", echo_handler)
request = ToolRequest(request_id="req-1", name="echo", args={"text": "lint passed"}, limits={"wall_ms": 2000})
print(asdict(registry.invoke(request)))
```

## CHAPTER http-interface

The HTTP interface exposes local run control to development tools and simple dashboards. It should be intentionally minimal. Endpoints accept JSON, return JSON, and do not serve static files. The server should bind to localhost by default unless the operator explicitly chooses another address. The interface is not a full job queue; it submits run descriptions and reports status. The scheduler and storage remain the authoritative execution machinery.

A standard set of routes includes health checks, run creation, run status, and cancellation. POST /runs creates a run and returns a run id. GET /runs/{id} returns status and task summaries. POST /runs/{id}/cancel requests cancellation. The server should not execute long work inside request handlers. It should enqueue the run or start a background scheduler and return immediately. This avoids HTTP timeouts and keeps the interface non-blocking.

Invariants include stable ids, JSON content type, bounded request bodies, and thread-safe state. Because http.server handlers may run in threads, shared dictionaries need a lock. The server should read exactly Content-Length bytes to avoid partial parsing or connection confusion. Error handling maps bad JSON to 400, unknown routes to 404, unknown runs to 404, and internal scheduler startup failures to 500. The worked example starts a threaded server on an ephemeral port, posts a small run, reads the created record, polls status, and shuts down cleanly.

The interface should also include a request timeout on the client side in examples and tests. Real deployments should add authentication, CSRF protection, or local socket access controls if the port may be reachable. The standard library server is adequate for local development when bound to loopback and kept simple. Production-facing APIs usually add a hardened reverse proxy, but the contract remains JSON status records.

```python
import json
import threading
import urllib.request
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

STATE = {"runs": {}, "lock": threading.Lock()}

class RunHandler(BaseHTTPRequestHandler):
    def log_message(self, format, *args):
        return

    def send_json(self, code, payload):
        body = json.dumps(payload, sort_keys=True).encode("utf-8")
        self.send_response(code)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def do_GET(self):
        if self.path == "/health":
            self.send_json(200, {"status": "ok"})
            return
        parts = self.path.strip("/").split("/")
        if len(parts) == 2 and parts[0] == "runs":
            with STATE["lock"]:
                run = STATE["runs"].get(parts[1])
            if run is None:
                self.send_json(404, {"error": "not found"})
                return
            self.send_json(200, run)
            return
        self.send_json(404, {"error": "unknown route"})

    def do_POST(self):
        if self.path != "/runs":
            self.send_json(404, {"error": "unknown route"})
            return
        length = int(self.headers.get("Content-Length", "0"))
        try:
            data = json.loads(self.rfile.read(length).decode("utf-8"))
        except json.JSONDecodeError:
            self.send_json(400, {"error": "invalid json"})
            return
        run_id = "run-" + str(len(STATE["runs"]) + 1)
        record = {"id": run_id, "status": "scheduled", "tasks": data.get("tasks", [])}
        with STATE["lock"]:
            STATE["runs"][run_id] = record
        self.send_json(201, record)

server = ThreadingHTTPServer(("127.0.0.1", 0), RunHandler)
thread = threading.Thread(target=server.serve_forever, daemon=True)
thread.start()
port = server.server_address[1]
health = json.loads(urllib.request.urlopen("http://127.0.0.1:" + str(port) + "/health", timeout=2).read())
request = urllib.request.Request(
    "http://127.0.0.1:" + str(port) + "/runs",
    data=json.dumps({"tasks": ["lint", "test"]}).encode("utf-8"),
    headers={"Content-Type": "application/json"},
)
created = json.loads(urllib.request.urlopen(request, timeout=2).read())
status = json.loads(urllib.request.urlopen("http://127.0.0.1:" + str(port) + "/runs/" + created["id"], timeout=2).read())
server.shutdown()
server.server_close()
thread.join(timeout=1)
print(health, created["id"], status["status"])
```

## CHAPTER cli-interface

The command line interface is the operator’s primary entry point. It should expose a few stable verbs: validate, run, status, and cancel. The CLI should never be responsible for complex scheduling logic. It parses arguments, constructs the runner, wires components, and prints machine-readable or human-readable output. For automation, stdout should contain structured JSON and stderr should contain logs. For interactive use, a human summary can be requested with a separate flag.

Argument parsing must reject ambiguous or unsafe combinations early. A run file must exist before scheduling begins. Worker count must be positive. Cancellation requires a run id that can be resolved through the workspace. Exit codes should be meaningful: zero for completed, one for task failure, two for usage or contract error, and three for cancellation. This makes CI integration predictable without parsing English text.

The CLI is also the boundary for workspace resolution. It should accept a root path and convert it to an absolute workspace object. It should acquire a lock if another runner may target the same directory. It should validate the manifest after ensuring directories. These steps prevent two operators from writing checkpoints into the same journal and corrupting recovery. The CLI should pass the workspace into every subsystem so no component invents its own default path.

Error handling should produce concise messages with enough context. A usage error should show the offending argument and expected values. A contract validation error should print the path and reason. A storage failure should distinguish permission errors from disk full. The worked example builds a small argparse command tree, validates a task JSON file, runs a simplified scheduler summary, and queries status. It uses a temporary directory so the example does not depend on leftover files.

```python
import argparse
import json
import os
import tempfile
from dataclasses import asdict, dataclass
from typing import Any, Dict

@dataclass(frozen=True)
class CliResult:
    command: str
    payload: Dict[str, Any]

class Runner:
    def validate(self, path: str) -> Dict[str, Any]:
        with open(path, encoding="utf-8") as handle:
            tasks = json.load(handle)
        if not isinstance(tasks, list):
            raise ValueError("task file must be a JSON list")
        for task in tasks:
            if "name" not in task or "deps" not in task:
                raise ValueError("each task needs name and deps")
        return {"valid": len(tasks)}

    def run(self, path: str, max_workers: int) -> Dict[str, Any]:
        summary = self.validate(path)
        if max_workers < 1:
            raise ValueError("max workers must be positive")
        summary.update({"status": "completed", "workers": max_workers})
        return summary

    def status(self, run_id: str) -> Dict[str, Any]:
        return {"id": run_id, "status": "completed"}

def build_parser():
    parser = argparse.ArgumentParser(prog="agent-task")
    sub = parser.add_subparsers(dest="command", required=True)
    validate = sub.add_parser("validate")
    validate.add_argument("--file", required=True)
    run = sub.add_parser("run")
    run.add_argument("--file", required=True)
    run.add_argument("--max-workers", type=int, default=4)
    status = sub.add_parser("status")
    status.add_argument("--run-id", required=True)
    return parser

def main(argv):
    parser = build_parser()
    args = parser.parse_args(argv)
    runner = Runner()
    if args.command == "validate":
        payload = runner.validate(args.file)
    elif args.command == "run":
        payload = runner.run(args.file, args.max_workers)
    else:
        payload = runner.status(args.run_id)
    return CliResult(args.command, payload)

with tempfile.TemporaryDirectory() as tmp:
    task_file = os.path.join(tmp, "tasks.json")
    with open(task_file, "w", encoding="utf-8") as handle:
        json.dump([{"name": "prepare", "deps": []}, {"name": "lint", "deps": ["prepare"]}], handle)
    print(asdict(main(["validate", "--file", task_file])))
    print(asdict(main(["run", "--file", task_file, "--max-workers", "2"])))
    print(asdict(main(["status", "--run-id", "demo"])))
```

## CHAPTER observability

Observability answers what happened, why it happened, and how long it took. Structured logs should emit one record per lifecycle event with run id, task name, timestamp, duration, status, and error taxonomy. Logs are not a database, but they are the fastest debugging surface. Metrics provide aggregate trends: task duration histograms, retry counts, cancellation counts, tool failure rates, scheduler queue depth, and journal write latency. The local runner should not rely on remote infrastructure to be usable, so it should write logs to stderr and expose counters in process memory or a small JSON metrics file.

Instrumentation must not change semantics. A logger that raises when a field contains unexpected characters can fail a task that would otherwise succeed. Formatters should serialize defensively and truncate long payloads. Metric labels should be bounded and normalized. A task name can be a label if the number of tasks is finite and reviewed; arbitrary user input should not become a metric label without cardinality limits. Error messages should be sanitized because tool output may contain secrets.

Trace context should connect journal events, scheduler logs, and tool results. A simple correlation id is enough. The run id identifies the graph, the task name identifies the node, and a request id identifies one tool attempt. If a task retries, each attempt gets a distinct request id while retaining the task id. This lets operators distinguish one slow task from repeated failed attempts.

Error handling in observability should be fail-open for logging when correctness already failed, but fail-closed for journal writes that are part of recovery. A log write failure can be printed to stderr, while an event journal write failure should stop scheduling because state durability is at stake. The worked example defines a structured logger and metrics counter, wraps a tool call, and prints both the result and counters. It shows the minimum signal needed to debug a local runner.

```python
import json
import logging
import sys
import time
from dataclasses import dataclass, field
from typing import Any, Dict

@dataclass
class Metrics:
    counters: Dict[str, int] = field(default_factory=dict)

    def inc(self, name: str, labels: Dict[str, str] = None) -> int:
        label_key = json.dumps(labels or {}, sort_keys=True)
        key = name + "|" + label_key
        self.counters[key] = self.counters.get(key, 0) + 1
        return self.counters[key]

class StructuredFormatter(logging.Formatter):
    def format(self, record: logging.LogRecord) -> str:
        data = {
            "level": record.levelname,
            "message": record.getMessage(),
            "timestamp": time.time(),
        }
        payload = getattr(record, "payload", {})
        if isinstance(payload, dict):
            data.update(payload)
        return json.dumps(data, sort_keys=True)

def get_logger() -> logging.Logger:
    logger = logging.getLogger("agent-task")
    if logger.handlers:
        return logger
    logger.setLevel(logging.INFO)
    handler = logging.StreamHandler(sys.stderr)
    handler.setFormatter(StructuredFormatter())
    logger.addHandler(handler)
    return logger

def instrument_tool(logger: logging.Logger, metrics: Metrics, name: str, work) -> Any:
    start = time.monotonic()
    logger.info("tool_started", extra={"payload": {"tool": name}})
    metrics.inc("tool_started", {"tool": name})
    try:
        result = work()
    except Exception as exc:
        metrics.inc("tool_failed", {"tool": name})
        logger.error("tool_failed", extra={"payload": {"tool": name, "error": str(exc)}})
        raise
    metrics.inc("tool_completed", {"tool": name})
    duration_ms = int((time.monotonic() - start) * 1000)
    logger.info("tool_finished", extra={"payload": {"tool": name, "duration_ms": duration_ms}})
    return result

metrics = Metrics()
logger = get_logger()
print(instrument_tool(logger, metrics, "python.lint", lambda: {"exit_code": 0}))
print(metrics.counters)
```

## CHAPTER security-boundaries

Security boundaries define what the runner may touch. The local agent may execute tools, so the boundary must be explicit. Paths should be restricted to allowed roots. Environment variables should be allowlisted. Executables should be registered rather than arbitrary strings from task input. Shell features should be disabled unless a tool intentionally requires them, and even then the command should be reviewed as a separate privilege. The default posture is deny-by-default.

Path validation must happen after resolving symlinks and relative components. A path that looks safe under a root can escape through a symlink or parent traversal if the implementation only compares prefixes textually. The workspace layer already provides helpers; security policy should add another layer for task arguments that reference files. For example, a lint argument may be inside the repo, but a tool result should not create paths outside the artifact root. Validation must happen before opening files, not after.

Environment filtering is often more important than process isolation. Python subprocess inherits many variables, and task input could indirectly influence behavior through PATH, PYTHONPATH, or locale settings. An allowlist keeps the tool environment predictable and reduces credential leakage. The runner should pass only PATH and any explicitly required variables. Tool-specific secrets should be injected by the operator or by a wrapper that the policy trusts, not by task expressions.

Command validation should reject shell invocation and arbitrary interpreters from task data. A registered subprocess tool may execute `python.lint` with controlled arguments, but user-provided command strings should not become argv elements without validation. The worked example creates a policy with an allowed temporary root, an allowed executable set, and an allowed environment key. It checks a safe artifact path, denies traversal outside the root, and rejects an unregistered executable. This demonstrates the core checks without requiring a sandbox outside the standard library.

```python
import os
import sys
import tempfile
from pathlib import Path
from typing import Dict, Mapping, Sequence

class SecurityError(Exception):
    pass

class SecurityPolicy:
    def __init__(self, allowed_roots: Sequence[Path], allowed_executables: Sequence[str], allowed_env: Sequence[str]) -> None:
        self.allowed_roots = tuple(path.resolve() for path in allowed_roots)
        self.allowed_executables = set(allowed_executables)
        self.allowed_env = set(allowed_env)

    def check_path(self, requested: Path) -> Path:
        candidate = requested.resolve()
        for root in self.allowed_roots:
            try:
                common = os.path.commonpath([str(root), str(candidate)])
            except ValueError:
                continue
            if common == str(root):
                return candidate
        raise SecurityError("path outside allowed roots")

    def check_command(self, command: Sequence[str]) -> None:
        if len(command) < 2:
            raise SecurityError("command must include executable and arguments")
        if command[0] not in self.allowed_executables:
            raise SecurityError("executable not allowed")
        if command[1] == "-c":
            raise SecurityError("inline execution is not allowed")

    def filtered_env(self, environment: Mapping[str, str]) -> Dict[str, str]:
        return {key: value for key, value in environment.items() if key in self.allowed_env}

with tempfile.TemporaryDirectory() as tmp:
    root = Path(tmp).resolve()
    policy = SecurityPolicy([root], [sys.executable], ["PATH"])
    safe = policy.check_path(Path("artifacts") / "lint.txt")
    inside = os.path.commonpath([str(root), str(safe)]) == str(root)
    env = policy.filtered_env(os.environ)
    print(inside, list(env))
    try:
        policy.check_path(Path(tmp).parent / "escape.txt")
    except SecurityError as exc:
        print(exc)
    try:
        policy.check_command(["/usr/bin/env", "echo", "hello"])
    except SecurityError as exc:
        print(exc)
```

## CHAPTER unit-testing

Unit tests should target invariants, not incidental implementation details. For this runner, the most valuable tests are small and deterministic: expression parsing, cycle detection, graph readiness, retry attempt counts, and cancellation token hierarchy. These tests should not depend on real subprocesses, network ports, or global time. Where timing is unavoidable, use very short deadlines or injectable clocks. The standard library unittest module provides structure without adding dependencies.

Tests must encode contract rules. A cycle detector test should fail if the detector returns no cycle for a known cyclic graph. A cancellation test should prove that parent cancellation reaches children and child cancellation does not reach the parent. A retry test should prove that nonretryable exceptions are rethrown immediately and retryable errors stop at max attempts. If a test only checks a happy path, it may hide a scheduling bug where a task runs twice or a dependency is ignored.

Error-path tests are just as important as success paths. For every failure mode, ask what state the journal and results should contain. If a task fails, dependents should be blocked. If a tool returns invalid JSON, the result should be failed with a message about serialization. If a checkpoint references a missing event sequence, recovery should skip stale events rather than apply them. These tests should assert exceptions and statuses, not just stdout.

The worked example tests cancellation tokens with unittest. It verifies parent-to-child propagation, independence of child cancellation, and cooperative sleep. The test suite is executed in the same script and prints success, so the example is self-contained and runnable without pytest. This pattern can be extended to parser tests, evaluator tests, graph tests, and storage tests.

```python
import threading
import unittest
from typing import List

class CancellationToken:
    def __init__(self, parent: "CancellationToken" = None) -> None:
        self.parent = parent
        self._event = threading.Event()
        self._children: List[CancellationToken] = []
        if parent is not None:
            parent._children.append(self)

    def cancel(self) -> None:
        self._event.set()
        for child in self._children:
            child.cancel()

    def is_cancelled(self) -> bool:
        return self._event.is_set()

    def sleep(self, seconds: float) -> bool:
        return self._event.wait(timeout=seconds)

class CancellationTests(unittest.TestCase):
    def test_parent_cancel_propagates_to_child(self):
        parent = CancellationToken()
        child = CancellationToken(parent)
        parent.cancel()
        self.assertTrue(child.is_cancelled())

    def test_child_cancel_does_not_cancel_parent(self):
        parent = CancellationToken()
        child = CancellationToken(parent)
        child.cancel()
        self.assertTrue(child.is_cancelled())
        self.assertFalse(parent.is_cancelled())

    def test_sleep_reports_cancelled_event(self):
        token = CancellationToken()
        threading.Timer(0.02, token.cancel).start()
        self.assertTrue(token.sleep(0.5))

suite = unittest.defaultTestLoader.loadTestsFromTestCase(CancellationTests)
result = unittest.TextTestRunner(verbosity=1).run(suite)
print("success", result.wasSuccessful())
```

## CHAPTER integration-testing

Integration tests prove that subsystems cooperate. For this runner, the important integration is scheduler, workspace storage, tool execution, and journal or artifact visibility. A good integration test uses a temporary workspace, a few dependent tasks, and tools that perform real but bounded side effects. It should assert that tasks execute in dependency order, that artifacts exist with expected content, that results carry completed status, and that independent tasks may overlap when worker capacity allows.

Integration tests must be isolated. Use temp directories, fixed run ids, and deterministic sleep durations. Do not write into the source tree. Do not depend on environment variables other than the current interpreter path. If a test spawns subprocesses, ensure every subprocess has a timeout and that the test waits for scheduler shutdown. Resource exhaustion in tests is a bug because it hides real failures under nondeterministic slowness.

The expected assertions should mirror production invariants. A failed dependency should prevent dependents from creating artifacts. A cancelled run should not report all tasks as completed. A completed run should have one journal event or result entry per task outcome. In this example, the test uses a compact scheduler, writes artifacts atomically, and verifies that prepare, lint, and test complete in order. The artifact content is simple but enough to show that the tool side effect actually happened.

Error handling should be checked too. Add a task that raises a controlled exception and assert that its dependent does not produce an artifact. Add a slow tool and assert that the scheduler returns within the test deadline. Integration tests often catch bugs that unit tests miss because scheduling state and storage state are separate objects until the run ends. The worked example asserts completed statuses and final artifact text, then prints the directory listing.

```python
import tempfile
from concurrent.futures import FIRST_COMPLETED, ThreadPoolExecutor, wait
from dataclasses import dataclass
from pathlib import Path
from typing import Dict, Tuple

@dataclass(frozen=True)
class Job:
    name: str
    deps: Tuple[str, ...]

def write_artifact(root: Path, name: str, content: str) -> None:
    artifact = root / (name + ".txt")
    temp = root / (name + ".tmp")
    temp.write_text(content, encoding="utf-8")
    temp.replace(artifact)

def run_jobs(jobs: Tuple[Job, ...], root: Path, max_workers: int = 2) -> Dict[str, Dict[str, str]]:
    completed = set()
    failed = set()
    pending = set()
    results: Dict[str, Dict[str, str]] = {}

    def execute(name: str) -> str:
        write_artifact(root, name, name + " done")
        return name

    with ThreadPoolExecutor(max_workers=max_workers) as pool:
        futures: Dict[object, str] = {}
        while True:
            submitted = False
            for job in jobs:
                if job.name in completed or job.name in failed or job.name in pending:
                    continue
                if any(dep in failed for dep in job.deps):
                    failed.add(job.name)
                    results[job.name] = {"status": "blocked"}
                    continue
                if all(dep in completed for dep in job.deps):
                    pending.add(job.name)
                    futures[pool.submit(execute, job.name)] = job.name
                    submitted = True
                    break
            if submitted:
                continue
            if not futures:
                break
            done, _ = wait(futures, timeout=0.05, return_when=FIRST_COMPLETED)
            for future in done:
                name = futures.pop(future, None)
                if name is None:
                    continue
                pending.discard(name)
                try:
                    payload = future.result()
                except Exception:
                    failed.add(name)
                    results[name] = {"status": "failed"}
                    continue
                completed.add(name)
                results[name] = {"status": "completed", "payload": payload}
    return results

with tempfile.TemporaryDirectory() as tmp:
    root = Path(tmp)
    jobs = (Job("prepare", ()), Job("lint", ("prepare",)), Job("test", ("lint",)))
    results = run_jobs(jobs, root)
    assert all(value["status"] == "completed" for value in results.values())
    assert (root / "lint.txt").read_text(encoding="utf-8") == "lint done"
    print(len(results), sorted(path.name for path in root.iterdir()))
```

## CHAPTER load-testing

Load testing measures how the runner behaves under many tasks and many dependencies. It is not the same as unit testing, because it exercises thread pools, queueing, storage writes, and scheduler loop latency. The goal is to find pathological scaling behavior: unbounded memory, thread starvation, dependency scans that run in quadratic time, or journal writes that serialize all tasks. A small local runner should handle dozens or hundreds of tasks without collapsing, and load tests should show where the curve bends.

Use synthetic work with bounded sleep and predictable durations. Randomization can be useful, but deterministic seeds make regressions reproducible. Measure wall-clock throughput, task completion p95, queue wait time, and peak active futures. If the scheduler scans all ready tasks after every completion, a large graph can become slow; load tests reveal that quickly. If the journal fsyncs after every event, throughput may drop sharply; load tests can compare batched durability modes.

Backpressure matters. The scheduler should not submit thousands of futures to a small pool and consume memory in queues. A ready loop that submits only while capacity exists keeps memory controlled. Worker count should be tested at realistic values, such as four, sixteen, or the number of cores times a factor. A local tool runner may also have subprocess limits, so too many subprocesses may cause system contention even when Python threads are fine.

Error handling in load tests should include failures. A graph with a failing high-fan-out task should not block unrelated independent work. A failing leaf should stop only its descendants. The worked example runs many independent tasks through a pool and reports throughput and p95 completion latency. This gives a baseline for scheduler overhead and shows how to add p95 computation without external libraries.

```python
import time
from concurrent.futures import ThreadPoolExecutor, as_completed
from dataclasses import dataclass
from typing import List

@dataclass(frozen=True)
class LoadJob:
    name: str

def timed_work(name: str, sleep_ms: float) -> str:
    time.sleep(sleep_ms / 1000.0)
    return name

def run_load(job_count: int, max_workers: int, sleep_ms: float) -> dict:
    jobs: List[LoadJob] = [LoadJob("job-" + str(index)) for index in range(job_count)]
    start = time.perf_counter()
    completion_times: List[float] = []
    with ThreadPoolExecutor(max_workers=max_workers) as pool:
        futures = {pool.submit(timed_work, job.name, sleep_ms): job.name for job in jobs}
        for future in as_completed(futures):
            future.result()
            completion_times.append(time.perf_counter() - start)
    elapsed = time.perf_counter() - start
    completion_times.sort()
    p95_index = max(0, int(len(completion_times) * 0.95) - 1)
    return {
        "completed": len(completion_times),
        "elapsed_seconds": round(elapsed, 3),
        "throughput_per_second": round(len(completion_times) / elapsed, 2),
        "p95_seconds": round(completion_times[p95_index], 3),
    }

report = run_load(job_count=200, max_workers=16, sleep_ms=2.0)
print(report)
```

## CHAPTER operations-and-examples

Operations concerns the runner after code is deployed. Operators need to answer whether a run is healthy, whether the journal is intact, whether tasks are orphaned, and whether artifacts are safe to delete. The local runner should provide scripts or CLI commands that read workspace state without mutating it. A summary should list completed tasks, failed tasks, running tasks inferred from the journal tail, integrity state, and timestamps. This turns debugging from guesswork into a checklist.

Integrity verification comes first. Before trusting status, verify that the event journal is continuous and hash-linked. A missing sequence, broken previous hash, or mismatched event hash means the state is suspect. The operator should preserve the corrupt journal and start a new run or use an explicitly approved repair path. Checkpoints should reference the last verified sequence. If a checkpoint has a higher sequence than the journal tail, recovery should not proceed automatically because the state is inconsistent.

Orphan detection is the next step. A task_started event without a task_finished event may mean the process died while running. Recovery can treat these as running only if the runner pid is still alive or the tool is idempotent. Otherwise the scheduler should reexecute or mark them failed. Artifacts from incomplete tasks should be quarantined or overwritten atomically on retry. The journal’s task_started and task_finished pairings give the evidence needed for this decision.

Error handling in operations should be conservative. A corrupt journal is not silently truncated. A missing artifact for a completed task is a serious alert. A completed task with a non-atomic temporary file indicates a storage bug. The worked example creates a small valid journal in a temporary workspace, verifies hash continuity, and prints a summary that includes completed and running tasks. This is the operational view an on-call engineer needs at the beginning of an incident.

```python
import hashlib
import json
import tempfile
from pathlib import Path
from typing import Dict

def hash_payload(event: Dict[str, object]) -> str:
    payload = {
        "seq": event["seq"],
        "run_id": event["run_id"],
        "name": event["name"],
        "data": event["data"],
        "previous_hash": event["previous_hash"],
    }
    serialized = json.dumps(payload, sort_keys=True, separators=(",", ":"))
    return hashlib.sha256(serialized.encode("utf-8")).hexdigest()

def verify_journal(path: Path) -> Dict[str, object]:
    previous = "root"
    expected_seq = 1
    completed = set()
    running = set()
    for line in path.read_text(encoding="utf-8").splitlines():
        if not line.strip():
            continue
        event = json.loads(line)
        if event["seq"] != expected_seq or event["previous_hash"] != previous:
            raise ValueError("journal sequence broken at " + str(event["seq"]))
        if hash_payload(event) != event["event_hash"]:
            raise ValueError("journal hash mismatch at " + str(event["seq"]))
        task = event.get("data", {}).get("task")
        if event["name"] == "task_started" and task:
            running.add(task)
        if event["name"] == "task_finished" and task:
            running.discard(task)
            if event["data"].get("status") == "completed":
                completed.add(task)
        previous = event["event_hash"]
        expected_seq += 1
    return {
        "events": expected_seq - 1,
        "integrity": "verified",
        "completed": sorted(completed),
        "running_after_journal": sorted(running),
    }

with tempfile.TemporaryDirectory() as tmp:
    journal = Path(tmp) / "events.jsonl"
    previous = "root"
    lines = []
    specs = [
        ("task_started", {"task": "lint"}),
        ("task_finished", {"task": "lint", "status": "completed"}),
        ("task_started", {"task": "test"}),
    ]
    for index, (name, data) in enumerate(specs, start=1):
        payload = {
            "seq": index,
            "run_id": "run-1",
            "name": name,
            "data": data,
            "previous_hash": previous,
        }
        digest = hash_payload(payload)
        payload["event_hash"] = digest
        lines.append(json.dumps(payload, sort_keys=True))
        previous = digest
    journal.write_text("\n".join(lines) + "\n", encoding="utf-8")
    print(verify_journal(journal))
```

